    const update = () => {
      if (gameState !== "PLAYING") return;

      const head = { x: snake[0].x + dx, y: snake[0].y + dy };

      if (head.x < 0 || head.x >= tileCount || head.y < 0 || head.y >= tileCount) {
        gameOver();
        return;
      }

      if (snake.some(part => part.x === head.x && part.y === head.y)) {
        gameOver();
        return;
      }

      snake.unshift(head);

      if (head.x === food.x && head.y === food.y) {
        score += 10;
        scoreEl.textContent = `SCORE: ${score}`;
        if (score > hi) {
          hi = score;
          hiEl.textContent = `HI: ${hi}`;
          localStorage.setItem("cyber_snake_hi", hi);
        }
        spawnFood();
      } else {
        snake.pop();
      }
    };

    const gameOver = () => {
      gameState = "OVER";
      clearInterval(gameInterval);
      draw();
    };

    const startWithDirection = (newDx, newDy) => {
      if (gameState === "START" || gameState === "OVER") {
        resetGame();
        gameState = "PLAYING";
        dx = newDx;
        dy = newDy;
        if (gameInterval) clearInterval(gameInterval);
        gameInterval = setInterval(() => {
          update();
          draw();
        }, 100);
        return;
      }
      if (gameState !== "PLAYING") return;

      if (newDx !== 0 && dx === 0) { dx = newDx; dy = 0; }
      if (newDy !== 0 && dy === 0) { dx = 0; dy = newDy; }
    };

    this.snakeGamePause = () => {
      if (gameState === "PLAYING") {
        gameState = "PAUSED";
        clearInterval(gameInterval);
      }
    };

    this.snakeGameReset = () => {
      gameState = "START";
      if (gameInterval) clearInterval(gameInterval);
      resetGame();
      draw();
    };

    window.addEventListener("keydown", (e) => {
      if (!overlay.classList.contains("is-active")) return;
      if (["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", " ", "w", "a", "s", "d", "W", "A", "S", "D"].includes(e.key)) {
        e.preventDefault();
      }

      if (e.key === " ") {
        if (gameState === "PLAYING") this.snakeGamePause();
        else if (gameState === "PAUSED") {
          gameState = "PLAYING";
          gameInterval = setInterval(() => { update(); draw(); }, 100);
        }
        return;
      }

      if (e.key === "ArrowUp" || e.key === "w" || e.key === "W") {
        startWithDirection(0, -1);
      } else if (e.key === "ArrowDown" || e.key === "s" || e.key === "S") {
        startWithDirection(0, 1);
      } else if (e.key === "ArrowLeft" || e.key === "a" || e.key === "A") {
        startWithDirection(-1, 0);
      } else if (e.key === "ArrowRight" || e.key === "d" || e.key === "D") {
        startWithDirection(1, 0);
