      accent: s.getPropertyValue("--green").trim() || "#20ef4f",
      dead: s.getPropertyValue("--green-dim").trim() || "#087d2a",
    };
  }

  function reset() {
    dino = { x: 60, y: GROUND - DINO_H, vy: 0, onGround: true };
