      btn.addEventListener("click", () => {
        const dir = btn.dataset.dir;
        if (dir === "UP") startWithDirection(0, -1);
        if (dir === "DOWN") startWithDirection(0, 1);
        if (dir === "LEFT") startWithDirection(-1, 0);
        if (dir === "RIGHT") startWithDirection(1, 0);
      });
    });

    this.snakeGameReset();
  }
