        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#ef2020";
        ctx.font = "bold 20px 'Space Grotesk', sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("GAME OVER", canvas.width / 2, canvas.height / 2 - 15);
