﻿import { Model } from '../../js/model.js';
import { View } from '../../js/view.js';
import { Controller } from '../../js/controller.js';

// Cyber Snake Game Module & Animated Interactive Icon in Juegos Folder
Object.assign(View, {
  renderSnakeIconAnimation(canvas) {
    const ctx = canvas.getContext("2d");
    let snake = [{x: 4, y: 3}, {x: 3, y: 3}, {x: 2, y: 3}];
    let food = {x: 8, y: 3};
    let dx = 1;
    let frame = 0;

    const interval = setInterval(() => {
      if (!document.body.contains(canvas)) {
        clearInterval(interval);
        return;
      }
      frame++;
      if (frame % 10 === 0) {
        const head = { x: snake[0].x + dx, y: snake[0].y };
        if (head.x >= 11 || head.x < 1) {
          dx = -dx;
          head.x += dx * 2;
        }
        snake.unshift(head);
        snake.pop();
      }

      ctx.fillStyle = "#090b0a";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.strokeStyle = "#1b221d";
      ctx.lineWidth = 0.5;
      for (let x = 0; x < canvas.width; x += 8) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, canvas.height); ctx.stroke();
      }
      for (let y = 0; y < canvas.height; y += 8) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(canvas.width, y); ctx.stroke();
      }

      const cellSize = 8;
      ctx.fillStyle = "#ef2020";
      ctx.shadowColor = "#ff3333";
      ctx.shadowBlur = 4;
      ctx.fillRect(food.x * cellSize + 1, food.y * cellSize + 1, cellSize - 2, cellSize - 2);
      ctx.shadowBlur = 0;

      snake.forEach((part, idx) => {
        ctx.fillStyle = idx === 0 ? "#20ef4f" : "#128a2c";
        ctx.fillRect(part.x * cellSize + 1, part.y * cellSize + 1, cellSize - 2, cellSize - 2);
      });
    }, 80);
  }
});

const originalRenderJuegos = View.renderJuegos;
View.renderJuegos = function(games) {
  const container = document.getElementById("juegos-body");
  if (!container) return;
