    const resetGame = () => {
      snake = [
        { x: 10, y: 10 },
        { x: 9, y: 10 },
        { x: 8, y: 10 }
      ];
      dx = 0;
      dy = 0;
      score = 0;
      scoreEl.textContent = `SCORE: ${score}`;
      spawnFood();
    };

    const spawnFood = () => {
      food = {
        x: Math.floor(Math.random() * tileCount),
        y: Math.floor(Math.random() * tileCount)
      };
      if (snake.some(part => part.x === food.x && part.y === food.y)) {
        spawnFood();
      }
    };

    const sprites = {
      headUp: [
        "....############....",
        "...##############...",
        "..##.##.####.##.##..",
        "..##.##.####.##.##..",
        "..##################..",
        "..##################..",
        "..##.############.##..",
        "..##.##.####.##.##..",
        "...################...",
        "....##############....",
        ".....############.....",
        "......##########......",
        ".......########.......",
