        "..##.##.####.##.##..",
        "..##.############.##..",
        "..##################..",
        "..##################..",
        "..##.##.####.##.##..",
        "..##.##.####.##.##..",
        "...##############...",
        "....############...."
      ],
      headLeft: [
        "........##########..",
        ".......############.",
        "......###.####.###..",
        ".....###.##.##.##...",
        "....################..",
        "...#################..",
        "...#################..",
        "....################..",
        ".....###.##.##.##...",
        "......###.####.###..",
        ".......############.",
