          else if (dx === -1) headSprite = sprites.headLeft;
          else if (dy === 1) headSprite = sprites.headDown;
          else if (dy === -1) headSprite = sprites.headUp;
          drawSprite(ctx, headSprite, x, y, grid, "#20ef4f", "#20ef4f");
        } else if (index === snake.length - 1) {
          drawSprite(ctx, sprites.tail, x, y, grid, "#15b838", "#128a2c");
        } else {
          drawSprite(ctx, sprites.body, x, y, grid, "#1ab53f", "#128a2c");
        }
      });

      if (gameState === "START") {
