        ctx.shadowColor = glowColor;
        ctx.shadowBlur = 8;
      }
      ctx.fillStyle = color;
      for (let r = 0; r < sprite.length; r++) {
        for (let c = 0; c < sprite[r].length; c++) {
          if (sprite[r][c] === '#') {
            ctx.fillRect(x + c * px, y + r * px, px + 0.5, px + 0.5);
