            <canvas class="snake-canvas" id="snake-game-canvas" width="448" height="448"></canvas>
          </div>
          <p class="snake-controls-hint">PRESS ARROW / WASD TO START IN THAT DIRECTION</p>
          <div class="snake-touch-pad">
